package com.example.commerce.cart; import java.util.Optional; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface CartRepository extends JpaRepository<Cart,Long>{@Query("select distinct c from Cart c left join fetch c.items i left join fetch i.product where c.user.id=:userId") Optional<Cart> findDetailedByUserId(@Param("userId") Long userId);}
